-- Genie views for the CBI posture agent. Replace <catalog>.<schema> and run once (needs CREATE VIEW on the schema
-- and SELECT on system.access.audit / system.access.inbound_network). Rolling 90-day window.
-- Generated by .claude/skills/cbi-posture/scripts/cbi_sql.py --emit-genie; edit there.

CREATE OR REPLACE VIEW <catalog>.<schema>.cbi_audit_access
COMMENT 'Audit events with source-IP class (public_v4/private_v4/ipv6/other), /24 network, principal type and client family. Last 90 days. workspace_id 0 = account level.'
AS WITH audit_raw AS (
  SELECT
    event_date,
    CAST(workspace_id AS STRING)                                         AS workspace_id,
    service_name,
    action_name,
    COALESCE(NULLIF(trim(user_identity.email), ''), NULLIF(trim(user_identity.subject_name), ''), 'UNKNOWN') AS principal,
    trim(source_ip_address)                                              AS source_ip,
    user_agent,
    response.status_code                                                 AS status_code
  FROM system.access.audit
  WHERE event_date >= date_sub(current_date(), 90)
    AND TRUE /* cbi:workspace-scope (all workspaces). To scope: workspace_id IN ('<id>', '0') */
    AND source_ip_address IS NOT NULL
    AND trim(source_ip_address) <> ''
),
audit_parsed AS (
  SELECT *,
    CASE WHEN source_ip RLIKE '^[0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}$' THEN
        CAST(split(source_ip, '[.]')[0] AS BIGINT) * 16777216
      + CAST(split(source_ip, '[.]')[1] AS BIGINT) * 65536
      + CAST(split(source_ip, '[.]')[2] AS BIGINT) * 256
      + CAST(split(source_ip, '[.]')[3] AS BIGINT)
    END AS ip_long
  FROM audit_raw
),
audit AS (
  SELECT *,
    CASE
      WHEN ip_long IS NOT NULL AND (
           ip_long BETWEEN 0 AND 16777215 /* 0.0.0.0/8 */
           OR ip_long BETWEEN 167772160 AND 184549375 /* 10.0.0.0/8 */
           OR ip_long BETWEEN 1681915904 AND 1686110207 /* 100.64.0.0/10 */
           OR ip_long BETWEEN 2130706432 AND 2147483647 /* 127.0.0.0/8 */
           OR ip_long BETWEEN 2851995648 AND 2852061183 /* 169.254.0.0/16 */
           OR ip_long BETWEEN 2886729728 AND 2887778303 /* 172.16.0.0/12 */
           OR ip_long BETWEEN 3221225984 AND 3221226239 /* 192.0.2.0/24 */
           OR ip_long BETWEEN 3232235520 AND 3232301055 /* 192.168.0.0/16 */
           OR ip_long BETWEEN 3323068416 AND 3323199487 /* 198.18.0.0/15 */
           OR ip_long BETWEEN 3325256704 AND 3325256959 /* 198.51.100.0/24 */
           OR ip_long BETWEEN 3405803776 AND 3405804031 /* 203.0.113.0/24 */
      ) THEN 'private_v4'
      WHEN ip_long IS NOT NULL THEN 'public_v4'
      WHEN source_ip LIKE '%:%' THEN 'ipv6'
      ELSE 'other'
    END AS ip_class,
    CASE WHEN ip_long IS NOT NULL
         THEN concat_ws('.', split(source_ip, '[.]')[0], split(source_ip, '[.]')[1],
                        split(source_ip, '[.]')[2], '0') || '/24'
    END AS network_24,
    CASE
      WHEN principal RLIKE '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        THEN 'service_principal'
      WHEN principal LIKE '%@%' THEN 'user'
      WHEN principal = 'UNKNOWN' THEN 'unknown'
      ELSE 'other'
    END AS principal_type,
    (status_code IS NULL OR status_code < 400) AS succeeded
  FROM audit_parsed
)
SELECT event_date, workspace_id, service_name, action_name, principal, principal_type,
       source_ip, ip_class, network_24, user_agent,
       CASE
      WHEN user_agent ILIKE '%powerbi%' OR user_agent ILIKE '%power bi%' OR user_agent ILIKE '%PBI%' THEN 'Power BI'
      WHEN user_agent ILIKE '%tableau%'                                   THEN 'Tableau'
      WHEN user_agent ILIKE '%dbt%'                                       THEN 'dbt'
      WHEN user_agent ILIKE '%fivetran%'                                  THEN 'Fivetran'
      WHEN user_agent ILIKE '%looker%'                                    THEN 'Looker'
      WHEN user_agent ILIKE '%chatgpt%' OR user_agent ILIKE '%openai%'    THEN 'ChatGPT'
      WHEN user_agent ILIKE '%claude%' OR user_agent ILIKE '%anthropic%'  THEN 'Claude'
      WHEN user_agent ILIKE '%terraform%'                                 THEN 'Terraform'
      WHEN user_agent ILIKE '%databricks-cli%' OR user_agent ILIKE '%cli/%' THEN 'Databricks CLI'
      WHEN user_agent ILIKE '%databricks-sdk%'                            THEN 'Databricks SDK'
      WHEN user_agent ILIKE '%jdbc%' OR user_agent ILIKE '%odbc%' OR user_agent ILIKE '%SimbaSpark%' THEN 'JDBC/ODBC'
      WHEN user_agent ILIKE '%mozilla%'                                   THEN 'Browser'
      WHEN user_agent IS NULL OR user_agent = ''                          THEN 'Unknown'
      ELSE 'Other'
    END AS client_family,
       status_code, succeeded
FROM audit;

CREATE OR REPLACE VIEW <catalog>.<schema>.cbi_inbound_events
COMMENT 'CBI policy evaluations from system.access.inbound_network. outcome = DENIED (enforced block) or DRY_RUN_DENIAL (would be blocked). Last 90 days.'
AS WITH inbound AS (
  SELECT
    CAST(workspace_id AS STRING) AS workspace_id,
    event_time,
    request_path,
    source.ip                    AS source_ip,
    authenticated_as,
    rule_label,
    CASE
      WHEN upper(policy_outcome) LIKE '%DRY%RUN%' THEN 'DRY_RUN_DENIAL'
      WHEN upper(policy_outcome) IN ('DENY', 'DENIED', 'DROP') THEN 'DENIED'
      ELSE upper(policy_outcome)
    END AS outcome
  FROM system.access.inbound_network
  WHERE event_time >= date_sub(current_date(), 90)
    AND TRUE /* cbi:workspace-scope (all workspaces). To scope: CAST(workspace_id AS STRING) IN ('<id>', '0') */
)
SELECT * FROM inbound;

-- Requires the collector to have run with --uc-schema <catalog>.<schema> at least once.
CREATE OR REPLACE VIEW <catalog>.<schema>.cbi_posture_latest
COMMENT 'Most recent posture snapshot per workspace (maturity level, policy mode, IP ACL / PrivateLink / egress state).'
AS SELECT * FROM <catalog>.<schema>.cbi_posture_workspaces
QUALIFY row_number() OVER (PARTITION BY workspace_id ORDER BY run_ts DESC) = 1;

CREATE OR REPLACE VIEW <catalog>.<schema>.cbi_findings_latest
COMMENT 'Findings from the most recent posture run.'
AS SELECT * FROM <catalog>.<schema>.cbi_posture_findings
WHERE run_id = (SELECT max_by(run_id, run_ts) FROM <catalog>.<schema>.cbi_posture_findings);
